-- SliceURL D1 (SQLite) schema, converted from the Supabase/Postgres schema.
-- Conventions:
--   * UUIDs are TEXT, generated by the default below (or by the Worker).
--   * Timestamps are ISO-8601 TEXT in UTC (same format Postgres/JS emit).
--   * Booleans are INTEGER 0/1 (the Worker converts them back to true/false).
--   * Arrays / JSON are TEXT holding JSON.
--   * Postgres enums become TEXT + CHECK.
--   * RLS policies are enforced in the Worker (src/lib/policies.ts).

PRAGMA foreign_keys = ON;

-- ============================================================ AUTH
CREATE TABLE users (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  email TEXT NOT NULL UNIQUE COLLATE NOCASE,
  password_hash TEXT,                      -- pbkdf2$... (new) or $2a$/$2b$ bcrypt (imported from Supabase)
  google_sub TEXT UNIQUE,
  google_email TEXT,
  email_confirmed_at TEXT,
  user_metadata TEXT NOT NULL DEFAULT '{}',
  last_sign_in_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE sessions (
  id TEXT PRIMARY KEY,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  token_hash TEXT NOT NULL UNIQUE,         -- sha256 of the bearer token
  expires_at TEXT NOT NULL,
  user_agent TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_sessions_user ON sessions(user_id);

CREATE TABLE auth_tokens (                 -- password recovery links, OAuth state
  token_hash TEXT PRIMARY KEY,
  kind TEXT NOT NULL CHECK (kind IN ('recovery','oauth_state')),
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  data TEXT,
  expires_at TEXT NOT NULL,
  used_at TEXT
);

-- ============================================================ CORE
CREATE TABLE profiles (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
  display_name TEXT,
  avatar_url TEXT,
  language TEXT DEFAULT 'en',
  theme TEXT DEFAULT 'system',
  security_mode TEXT DEFAULT 'warn',
  auto_copy_enabled INTEGER DEFAULT 1,
  auto_dashboard_refresh INTEGER DEFAULT 1,
  auto_redirect_enabled INTEGER DEFAULT 0,
  email_alerts_enabled INTEGER DEFAULT 1,
  link_preview_enabled INTEGER DEFAULT 0,
  google_email TEXT,
  google_linked INTEGER DEFAULT 0,
  has_password INTEGER DEFAULT 1,
  scheduled_deletion_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE user_roles (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  role TEXT NOT NULL CHECK (role IN ('admin','moderator','user')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  UNIQUE (user_id, role)
);

CREATE TABLE folders (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT NOT NULL,
  color TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_folders_user ON folders(user_id);

CREATE TABLE api_keys (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name TEXT,
  key_hash TEXT NOT NULL UNIQUE,
  key_prefix TEXT NOT NULL,
  status TEXT NOT NULL DEFAULT 'active' CHECK (status IN ('active','revoked')),
  rate_limit_daily INTEGER NOT NULL DEFAULT 1000,
  requests_today INTEGER NOT NULL DEFAULT 0,
  rate_limit_reset_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now','+1 day')),
  last_request_at TEXT,
  revoked_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_api_keys_user ON api_keys(user_id);

CREATE TABLE links (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  user_id TEXT REFERENCES users(id) ON DELETE CASCADE,
  original_url TEXT NOT NULL,
  short_code TEXT NOT NULL UNIQUE,
  custom_slug TEXT,
  title TEXT,
  folder_id TEXT REFERENCES folders(id) ON DELETE SET NULL,
  api_key_id TEXT REFERENCES api_keys(id) ON DELETE SET NULL,
  api_source INTEGER DEFAULT 0,
  batch_id TEXT,
  click_count INTEGER DEFAULT 0,
  max_clicks INTEGER,
  expires_at TEXT,
  last_clicked_at TEXT,
  password_hash TEXT,
  is_password_protected INTEGER DEFAULT 0,
  is_private INTEGER DEFAULT 0,
  is_favorite INTEGER DEFAULT 0,
  is_pinned INTEGER DEFAULT 0,
  is_creepy INTEGER DEFAULT 0,
  creepy_style TEXT,
  creepy_extension TEXT,
  is_broken INTEGER DEFAULT 0,
  health_status TEXT DEFAULT 'active' CHECK (health_status IS NULL OR health_status IN ('active','low_activity','inactive','broken')),
  last_health_check TEXT,
  notify_on_broken INTEGER DEFAULT 0,
  safety_status TEXT,
  last_scanned_at TEXT,
  link_preview_enabled INTEGER NOT NULL DEFAULT 0,
  facebook_pixel TEXT,
  google_pixel TEXT,
  custom_og_title TEXT,
  custom_og_description TEXT,
  custom_og_image TEXT,
  custom_favicon TEXT,
  order_index INTEGER,
  slice_duration_ms INTEGER,
  utm_enabled INTEGER DEFAULT 0,
  utm_source TEXT,
  utm_medium TEXT,
  utm_campaign TEXT,
  utm_term TEXT,
  utm_content TEXT,
  final_utm_url TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_links_user ON links(user_id, created_at DESC);
CREATE INDEX idx_links_custom_slug ON links(custom_slug);
CREATE INDEX idx_links_batch ON links(batch_id);

CREATE TABLE clicks (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  link_id TEXT NOT NULL REFERENCES links(id) ON DELETE CASCADE,
  clicked_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  redirected_at TEXT,
  ip_address TEXT,
  user_agent TEXT,
  referrer TEXT,
  country TEXT,
  city TEXT,
  device_type TEXT,
  browser TEXT,
  os TEXT,
  is_unique INTEGER DEFAULT 1
);
CREATE INDEX idx_clicks_link_time ON clicks(link_id, clicked_at DESC);
CREATE INDEX idx_clicks_link_ip ON clicks(link_id, ip_address);

CREATE TABLE utm_data (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  link_id TEXT NOT NULL UNIQUE REFERENCES links(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  final_url TEXT NOT NULL,
  utm_source TEXT, utm_medium TEXT, utm_campaign TEXT, utm_term TEXT, utm_content TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE qr_designs (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  link_id TEXT NOT NULL UNIQUE REFERENCES links(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  fg_color TEXT NOT NULL DEFAULT '#000000',
  bg_color TEXT NOT NULL DEFAULT '#FFFFFF',
  shape TEXT NOT NULL DEFAULT 'square',
  corner_radius INTEGER NOT NULL DEFAULT 0,
  padding INTEGER NOT NULL DEFAULT 16,
  logo_url TEXT,
  logo_size INTEGER NOT NULL DEFAULT 20,
  frame_type TEXT,
  frame_text TEXT,
  gradient_enabled INTEGER NOT NULL DEFAULT 0,
  gradient_type TEXT NOT NULL DEFAULT 'linear',
  gradient_start TEXT,
  gradient_end TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE shared_analytics (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  link_id TEXT NOT NULL REFERENCES links(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  share_token TEXT NOT NULL UNIQUE,
  password_hash TEXT,
  expires_at TEXT,
  is_active INTEGER NOT NULL DEFAULT 1,
  views_count INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE user_personas (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  user_id TEXT NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
  persona TEXT NOT NULL DEFAULT 'casual' CHECK (persona IN ('influencer','marketer','agency','casual')),
  total_links INTEGER NOT NULL DEFAULT 0,
  total_clicks INTEGER NOT NULL DEFAULT 0,
  folder_count INTEGER NOT NULL DEFAULT 0,
  links_this_week INTEGER NOT NULL DEFAULT 0,
  utm_usage_count INTEGER NOT NULL DEFAULT 0,
  last_calculated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE announcements (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  message TEXT NOT NULL,
  is_active INTEGER DEFAULT 1,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE global_counters (
  id TEXT PRIMARY KEY,
  total_clicks INTEGER NOT NULL DEFAULT 0,
  total_links_created INTEGER NOT NULL DEFAULT 0,
  total_signups INTEGER NOT NULL DEFAULT 0,
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
INSERT INTO global_counters (id) VALUES ('main');

-- Replaces the Postgres increment_*_counter triggers
CREATE TRIGGER trg_links_counter AFTER INSERT ON links
BEGIN UPDATE global_counters SET total_links_created = total_links_created + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 'main'; END;
CREATE TRIGGER trg_clicks_counter AFTER INSERT ON clicks
BEGIN UPDATE global_counters SET total_clicks = total_clicks + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 'main'; END;
CREATE TRIGGER trg_profiles_counter AFTER INSERT ON profiles
BEGIN UPDATE global_counters SET total_signups = total_signups + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ','now') WHERE id = 'main'; END;

CREATE TABLE ip_geo_cache (
  ip_address TEXT PRIMARY KEY,
  country TEXT, city TEXT, region TEXT, provider TEXT,
  cached_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  expires_at TEXT NOT NULL
);

CREATE TABLE geo_backfill_allowlist (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  ip_address TEXT NOT NULL, city TEXT NOT NULL, country TEXT, region TEXT, notes TEXT,
  source TEXT NOT NULL DEFAULT 'manual',
  approved_by TEXT NOT NULL,
  approved_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  applied_at TEXT, rows_updated INTEGER
);

CREATE TABLE geo_backfill_audit (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  ip_address TEXT NOT NULL, city TEXT NOT NULL, country TEXT, region TEXT,
  rows_updated INTEGER NOT NULL DEFAULT 0,
  performed_by TEXT NOT NULL,
  performed_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- ============================================================ FILES (SliceBox / LittleSlice / apps)
CREATE TABLE slicebox_files (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  file_id TEXT NOT NULL UNIQUE,
  short_code TEXT UNIQUE,
  user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  storage_path TEXT NOT NULL,             -- R2 object key, e.g. slicebox/uploads/<id>/<name>
  original_name TEXT NOT NULL,
  mime_type TEXT NOT NULL,
  file_size INTEGER NOT NULL,
  service_type TEXT DEFAULT 'slicebox',
  password_hash TEXT,
  delete_token TEXT NOT NULL,
  is_encrypted INTEGER DEFAULT 0,
  encryption_iv TEXT,
  download_count INTEGER DEFAULT 0,
  expires_at TEXT,
  is_deleted INTEGER DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE INDEX idx_slicebox_expiry ON slicebox_files(is_deleted, expires_at);

CREATE TABLE app_listings (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  owner_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  file_id TEXT NOT NULL,
  app_name TEXT NOT NULL,
  short_code TEXT UNIQUE,
  short_description TEXT, full_description TEXT, whats_new TEXT,
  category TEXT, age_rating TEXT,
  developer_name TEXT, developer_url TEXT,
  icon_url TEXT, promo_banner_url TEXT,
  screenshots TEXT,                         -- JSON array
  version_name TEXT, version_code TEXT, release_date TEXT,
  is_published INTEGER DEFAULT 0,
  rating_avg REAL DEFAULT 0,
  rating_count INTEGER DEFAULT 0,
  total_downloads INTEGER DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE app_reviews (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  app_id TEXT NOT NULL REFERENCES app_listings(id) ON DELETE CASCADE,
  user_id TEXT REFERENCES users(id) ON DELETE SET NULL,
  display_name TEXT,
  rating INTEGER NOT NULL CHECK (rating BETWEEN 1 AND 5),
  review_text TEXT,
  ip_address TEXT,
  browser_fingerprint TEXT,
  deleted_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT
);
CREATE UNIQUE INDEX idx_app_reviews_ip_unique ON app_reviews(app_id, ip_address) WHERE deleted_at IS NULL;

-- ============================================================ FEEDBACK
CREATE TABLE feedback_requests (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  user_email TEXT,
  product TEXT NOT NULL,
  request_type TEXT NOT NULL,
  title TEXT NOT NULL,
  description TEXT NOT NULL,
  priority TEXT,
  status TEXT NOT NULL DEFAULT 'new',
  page_url TEXT, browser TEXT, os TEXT, device TEXT,
  screenshot_url TEXT,
  admin_notes TEXT,
  is_read INTEGER NOT NULL DEFAULT 0,
  is_important INTEGER NOT NULL DEFAULT 0,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

-- ============================================================ PAYMENTS
CREATE TABLE orders (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  order_number TEXT NOT NULL UNIQUE DEFAULT ('ORD-' || upper(hex(randomblob(6)))),
  plan_id TEXT NOT NULL,
  billing_cycle TEXT NOT NULL CHECK (billing_cycle IN ('monthly','yearly')),
  amount REAL NOT NULL, tax REAL NOT NULL DEFAULT 0, total REAL NOT NULL,
  currency TEXT NOT NULL DEFAULT 'INR',
  status TEXT NOT NULL DEFAULT 'created' CHECK (status IN ('created','pending','success','failed','refunded','cancelled')),
  dodo_payment_id TEXT, dodo_session_id TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE payments (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  order_id TEXT NOT NULL REFERENCES orders(id) ON DELETE CASCADE,
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  provider TEXT NOT NULL,
  provider_order_id TEXT, provider_txn_id TEXT,
  amount REAL NOT NULL,
  status TEXT NOT NULL DEFAULT 'created' CHECK (status IN ('created','pending','success','failed','refunded','cancelled')),
  raw_response TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
CREATE UNIQUE INDEX idx_payments_provider_txn ON payments(provider, provider_txn_id) WHERE provider_txn_id IS NOT NULL;

CREATE TABLE subscriptions (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  user_id TEXT NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  plan_id TEXT NOT NULL,
  billing_cycle TEXT NOT NULL CHECK (billing_cycle IN ('monthly','yearly')),
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('active','expired','cancelled','pending','failed')),
  current_period_start TEXT, current_period_end TEXT,
  cancel_at_period_end INTEGER NOT NULL DEFAULT 0,
  dodo_subscription_id TEXT UNIQUE,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE paytm_settings (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  env TEXT NOT NULL DEFAULT 'staging',
  merchant_id TEXT, merchant_key TEXT,
  website TEXT NOT NULL DEFAULT 'WEBSTAGING',
  is_active INTEGER NOT NULL DEFAULT 0,
  updated_by TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE paytm_callback_logs (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  event_type TEXT NOT NULL,
  paytm_order_id TEXT, paytm_txn_id TEXT, payment_status TEXT, status TEXT,
  http_status INTEGER, verification_error TEXT,
  raw_headers TEXT, raw_payload TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE dodo_settings (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  env TEXT NOT NULL DEFAULT 'test',
  api_key TEXT, webhook_secret TEXT,
  product_pro_monthly TEXT, product_pro_yearly TEXT,
  product_business_monthly TEXT, product_business_yearly TEXT,
  reconciliation_token TEXT NOT NULL DEFAULT (lower(hex(randomblob(24)))),
  is_active INTEGER NOT NULL DEFAULT 0,
  updated_by TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE dodo_webhook_logs (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  webhook_id TEXT UNIQUE,
  event_type TEXT NOT NULL,
  order_id TEXT, dodo_payment_id TEXT, dodo_subscription_id TEXT,
  status TEXT, http_status INTEGER, verification_error TEXT,
  raw_payload TEXT,
  processed_at TEXT,
  replay_count INTEGER NOT NULL DEFAULT 0,
  last_replayed_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE merchant_api_keys (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  name TEXT NOT NULL,
  key_hash TEXT NOT NULL UNIQUE,
  key_prefix TEXT NOT NULL,
  is_active INTEGER NOT NULL DEFAULT 1,
  last_used_at TEXT,
  created_by TEXT REFERENCES users(id) ON DELETE SET NULL,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);

CREATE TABLE merchant_orders (
  id TEXT PRIMARY KEY DEFAULT (lower(hex(randomblob(4)))||'-'||lower(hex(randomblob(2)))||'-4'||substr(lower(hex(randomblob(2))),2)||'-'||substr('89ab',abs(random())%4+1,1)||substr(lower(hex(randomblob(2))),2)||'-'||lower(hex(randomblob(6)))),
  order_number TEXT NOT NULL UNIQUE,
  api_key_id TEXT REFERENCES merchant_api_keys(id) ON DELETE SET NULL,
  external_order_id TEXT,
  amount REAL NOT NULL,
  currency TEXT NOT NULL DEFAULT 'INR',
  description TEXT,
  customer_name TEXT, customer_email TEXT, customer_phone TEXT,
  callback_url TEXT, return_url TEXT,
  status TEXT NOT NULL DEFAULT 'created',
  paytm_order_id TEXT UNIQUE, paytm_txn_id TEXT, txn_token TEXT,
  metadata TEXT, raw_response TEXT,
  verified_at TEXT,
  created_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now')),
  updated_at TEXT NOT NULL DEFAULT (strftime('%Y-%m-%dT%H:%M:%fZ','now'))
);
